// ---- catalog.json ----

export interface CatalogClip {
  id: string; name: string; description?: string; project?: string; sourceFileName?: string
  durationSec: number; sampleRate: number; channels: number
  effects: unknown[]; features: HapticFeatures
}
export interface Catalog {
  format: 'hapbeat-catalog@1'
  studioVersion: string
  generatedAt: string
  clips: CatalogClip[]
  effectTypes: Record<string, { params: Record<string, unknown> }>
  recipe: unknown
}

const featureCache = new WeakMap<AudioBuffer, HapticFeatures>()
function bufferFeatures(buffer: AudioBuffer): HapticFeatures {
  let features = featureCache.get(buffer)
  if (!features) {
    features = computeFeatures(mixToMono(Array.from({ length: buffer.numberOfChannels }, (_, ch) => buffer.getChannelData(ch))), buffer.sampleRate)
    featureCache.set(buffer, features)
  }
  return features
}

/** Working-buffer features are cached per AudioBuffer (buffers are immutable in the editor). */
export function buildCatalog(documents: EditorDocument[], studioVersion: string, generatedAt: string): Catalog {
  return {
    format: 'hapbeat-catalog@1', studioVersion, generatedAt,
    clips: documents.map(({ clip, effects }) => ({
      id: clip.id, name: clip.name, description: clip.description, project: clip.project, sourceFileName: clip.sourceFileName,
      durationSec: Math.round(clip.buffer.duration * 1e4) / 1e4, sampleRate: clip.buffer.sampleRate, channels: clip.buffer.numberOfChannels,
      effects: effects.filter(e => e.enabled).map(e => e.params),
      features: bufferFeatures(clip.buffer),
    })),
    effectTypes: Object.fromEntries(Object.entries(EFFECT_RANGES).map(([type, params]) => [type, { params }])),
    recipe: RECIPE_RANGES,
  }
}
